export const languages=['pt','fr','en'];
export const dictionaries={pt:{},fr:Object.fromEntries(rows.map(r=>[r[0],r[1]])),en:Object.fromEntries(rows.map(r=>[r[0],r[2]]))};
export function translate(source,lang='pt'){return dictionaries[lang]?.[source]||source;}
export function language(value){return languages.includes(value)?value:'pt';}
